# Builds data/prcggm_example.rda from the example data of the paper
# repository (https://github.com/AlessiaMapelli/Prior-informed-conditional-GGMs,
# Computational_templates/Example_data.RData). That file was generated by
# Simulation_analysis/Example_data/Simulate_example_data.R with n = 1000,
# p = 10, one binary covariate and a perfect prior.
# Run from the package root after copying Example_data.RData to data-raw/.

e <- new.env()
load("data-raw/Example_data.RData", envir = e)

x <- as.matrix(e$expression_data)
rownames(x) <- NULL
prior <- unname(as.matrix(e$ppi_weight_matrix))
dimnames(prior) <- list(colnames(x), colnames(x))
covariates <- e$covariate_data
rownames(covariates) <- NULL

prcggm_example <- list(x = x, covariates = covariates, prior = prior)
save(prcggm_example, file = "data/prcggm_example.rda", compress = "xz")
